<script setup>import{router}from'@inertiajs/vue3';import{reactive}from'vue';import AppLayout from'../../Layouts/AppLayout.vue';import ProductCard from'../../Components/ProductCard.vue';import Pagination from'../../Components/Pagination.vue';import SeoHead from'../../Components/SeoHead.vue';const props=defineProps({products:Object,categories:Array,brands:Array,selectedCategory:Object,filters:Object});const f=reactive({...props.filters});const apply=()=>router.get('/shop',f,{preserveState:true,replace:true});</script><template><AppLayout><SeoHead :title="selectedCategory?.name||'Shop electronics'" description="Browse electronics, phones, computers, accessories and networking products from Prinx Electronics."/><div class="container-shell py-8"><div><p class="section-kicker">Prinx catalogue</p><h1 class="section-title">{{selectedCategory?.name||'All products'}}</h1></div><div class="mt-5 grid gap-3 rounded-[10px] border bg-white p-3 md:grid-cols-4"><input v-model="f.search" class="input" placeholder="Search products" @keyup.enter="apply"><select v-model="f.category" class="input" @change="apply"><option value="">All categories</option><option v-for="c in categories" :key="c.id" :value="c.slug">{{c.name}}</option></select><select v-model="f.brand" class="input" @change="apply"><option value="">All brands</option><option v-for="b in brands" :key="b.id" :value="b.slug">{{b.name}}</option></select><select v-model="f.sort" class="input" @change="apply"><option value="">Recommended</option><option value="newest">Newest</option><option value="price_low">Price low to high</option><option value="price_high">Price high to low</option><option value="name">Name</option></select></div><div class="mt-6 grid grid-cols-2 gap-3 md:grid-cols-3 lg:grid-cols-4"><ProductCard v-for="p in products.data" :key="p.id" :product="p" compact-mobile/></div><div v-if="!products.data.length" class="card mt-6 p-10 text-center text-slate-500">No products matched your filters.</div><Pagination :links="products.links"/></div></AppLayout></template>
